// SPDX-License-Identifier: Apache-2.0
//! Generated-code detection: header markers and well-known generated paths.
//!
//! Generated files (protobuf output, `wrangler types`, code generators) carry no design: their
//! thousands of declarations drown the hubs of a graph, so a build skips them unless asked to
//! include them. A file counts as generated when one of the comment lines at its top carries a
//! generator marker, or when its path is a well-known generated location.

/// Header lines inspected for a marker.
const HEADER_LINES: usize = 24;

/// Case-insensitive markers of a generator header.
const MARKERS: &[&str] = &[
    "@generated",
    "generated by",
    "generated with",
    "do not edit",
    "do not modify",
    "code generated",
    "auto-generated",
    "autogenerated",
    "automatically generated",
    "this file is generated",
    "this file was generated",
    "this file has been generated",
];

/// Comment openers; a marker only counts on a line that starts with one.
const COMMENT_LEADERS: &[&str] = &["//", "/*", "*", "#", "<!--", "--", ";"];

/// Directory names that hold generated output wherever they appear.
const GENERATED_DIRS: &[&str] = &["generated", "__generated__", ".generated", "gen-src"];

/// A `gen` directory counts only below one of these (`pb/gen`, `proto/gen`).
const GEN_PARENTS: &[&str] = &["pb", "proto", "protos", "protobuf", "grpc", "openapi", "api"];

/// File name suffixes of generated output.
const GENERATED_SUFFIXES: &[&str] = &[
    ".pb.rs",
    ".pb.go",
    ".pb.ts",
    ".pb.js",
    "_pb.ts",
    "_pb.js",
    "_pb.d.ts",
    "_grpc_pb.js",
    ".generated.ts",
    ".generated.rs",
    ".generated.js",
    ".g.rs",
    ".g.ts",
    "-generated.ts",
    ".min.js",
    ".bundle.js",
];

/// Why a file is generated, `None` when it is hand-written.
///
/// `head` is the beginning of the file (the first kilobytes are enough).
#[must_use]
pub fn detect(path: &str, head: &[u8]) -> Option<&'static str> {
    if let Some(reason) = by_path(path) {
        return Some(reason);
    }
    by_header(path, head)
}

fn by_path(path: &str) -> Option<&'static str> {
    let lower = path.to_ascii_lowercase();
    let mut parts: Vec<&str> = lower.split('/').collect();
    let name = parts.pop().unwrap_or("");
    if GENERATED_SUFFIXES.iter().any(|s| name.ends_with(s)) {
        return Some("generated file name");
    }
    for (i, part) in parts.iter().enumerate() {
        if GENERATED_DIRS.contains(part) {
            return Some("generated directory");
        }
        if *part == "gen" && i > 0 && GEN_PARENTS.contains(&parts[i - 1]) {
            return Some("generated directory");
        }
    }
    None
}

fn by_header(path: &str, head: &[u8]) -> Option<&'static str> {
    let text = String::from_utf8_lossy(head);
    for line in text.lines().take(HEADER_LINES) {
        let trimmed = line.trim_start();
        if !COMMENT_LEADERS.iter().any(|c| trimmed.starts_with(c)) {
            continue;
        }
        // `//!` and `///` document the file's own code; a generator header is a plain comment.
        if trimmed.starts_with("//!") || trimmed.starts_with("///") {
            continue;
        }
        let lower = trimmed.to_ascii_lowercase();
        if MARKERS.iter().any(|m| lower.contains(m)) {
            return Some(if path.ends_with(".d.ts") {
                "generated declarations"
            } else {
                "generator header"
            });
        }
    }
    None
}

#[cfg(test)]
mod tests {
    use super::detect;

    #[test]
    fn header_markers_on_comment_lines_mark_generated_files() {
        for head in [
            "// This file is @generated by prost-build.\npub struct A;",
            "/* eslint-disable */\n// Generated by Wrangler by running `wrangler types`\ninterface Env {}",
            "// Code generated by protoc-gen-go. DO NOT EDIT.\npackage x",
            "# DO NOT EDIT: generated by make\nx = 1",
            "/**\n * Autogenerated by the schema compiler\n */\nexport {}",
        ] {
            assert!(detect("src/a.rs", head.as_bytes()).is_some(), "{head}");
        }
        assert_eq!(
            detect(
                "cloudflare/worker-configuration.d.ts",
                b"// Generated by Wrangler by running `wrangler types`\n"
            ),
            Some("generated declarations")
        );
    }

    #[test]
    fn plain_code_that_mentions_a_marker_is_not_generated() {
        for head in [
            "use std::fmt;\nfn a() { /* no marker here */ }",
            "//! Generated by the build script of `xtask`: documentation of the module.\nfn a() {}",
            "fn a() { let s = \"@generated\"; }",
            "pub fn b() {}\n",
        ] {
            assert!(detect("src/a.rs", head.as_bytes()).is_none(), "{head}");
        }
        // The marker must be in the header, not deep in the file.
        let deep = format!("{}// generated by a tool\n", "fn x() {}\n".repeat(40));
        assert!(detect("src/a.rs", deep.as_bytes()).is_none());
    }

    #[test]
    fn well_known_generated_paths_are_detected() {
        for path in [
            "crates/fw-a2a/src/pb/gen/lf.a2a.v1.rs",
            "src/google/stitch/generated/src/types.ts",
            "api/schema.pb.go",
            "web/dist/app.min.js",
            "src/lib.generated.ts",
        ] {
            assert!(detect(path, b"fn a() {}").is_some(), "{path}");
        }
        for path in ["crates/gen-tools/src/lib.rs", "src/gen/mod.rs", "src/generate.rs"] {
            assert!(detect(path, b"fn a() {}").is_none(), "{path}");
        }
    }
}
